CREATE TABLE "StorefrontPage" (
  "slug" TEXT NOT NULL,
  "title" TEXT NOT NULL,
  "eyebrow" TEXT NOT NULL DEFAULT '',
  "lead" TEXT NOT NULL DEFAULT '',
  "seoDescription" TEXT,
  "blocks" JSONB NOT NULL,
  "isActive" BOOLEAN NOT NULL DEFAULT true,
  "reviewRequired" BOOLEAN NOT NULL DEFAULT false,
  "revision" INTEGER NOT NULL DEFAULT 1,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "StorefrontPage_pkey" PRIMARY KEY ("slug")
);

INSERT INTO "StorefrontPage" ("slug", "title", "eyebrow", "lead", "blocks", "reviewRequired", "updatedAt") VALUES
('about', 'Создано мастером. Для мастеров.', 'О бренде', 'SARKISIAN — профессиональные материалы для маникюра под личным контролем Светланы Саркисян. В основе бренда — опыт мастера и внимание к ежедневной работе.', $$[
 {"id":"philosophy","title":"Понимаем профессию изнутри","body":"Хороший материал помогает сосредоточиться на клиенте и результате. Поэтому нам важны не только внешний вид продукта, но и то, насколько с ним удобно работать каждый день.\nБренд объединяет материалы и инструменты для мастеров, которые ценят понятный выбор и внимательное отношение к своей работе."},
 {"id":"collection","title":"Всё для вашей техники","body":"В каталоге представлены гели, гель-лаки, базы, топы, фрезы и инструменты. В карточках товаров можно посмотреть фотографии, описание, стоимость и доступные варианты.\nВыбирайте продукты под привычную технику и задачи. Если сомневаетесь, напишите нам: поможем разобраться в ассортименте, не обещая универсального решения для всех."},
 {"id":"care","title":"Забота не заканчивается покупкой","body":"От выбора материала до вопросов по заказу — команда магазина остаётся на связи. Заказы, обращения и история покупок доступны в личном кабинете.\nСистема лояльности помогает возвращаться к любимым продуктам. Актуальный баланс и условия использования бонусов отображаются в вашем аккаунте."},
 {"id":"professionals","title":"Для салонов и профессионалов","body":"Для B2B-клиентов предусмотрен отдельный кабинет: заказы для бизнеса, работа с собственной базой клиентов и запись на услуги.\nХотите работать с SARKISIAN как профессиональный партнёр? Перейдите во вход B2B или свяжитесь с нами, чтобы обсудить условия сотрудничества."}
]$$::jsonb, false, CURRENT_TIMESTAMP),
('delivery', 'Доставка и оплата', 'Покупать удобно', 'От выбора продукта до получения заказа — понятные шаги и команда, которая поможет разобраться с деталями.', $$[
 {"id":"order","title":"Как оформить заказ","body":"Выберите товары, укажите количество и добавьте их в корзину. Перед оформлением проверьте состав заказа и контактные данные получателя.\nДля адресной доставки понадобятся город, улица, дом и телефон. Для B2B-заказов используются реквизиты и условия вашего профессионального кабинета."},
 {"id":"payment","title":"Оплата заказа","body":"Стоимость товаров отображается в рублях. В новой платформе онлайн-оплата проводится через подключённого платёжного провайдера; доступные способы показываются на его странице оплаты.\nДанные банковской карты вводятся на странице платёжного сервиса, а не в формах магазина. После оплаты её результат можно проверить в истории заказа. Если платёж не завершён, обратитесь к нам с номером заказа."},
 {"id":"shipping","title":"Получение заказа","body":"Магазин отправляет заказы по России. На действующем сайте используется Ozon Доставка; для новой платформы службы доставки подключаются и проверяются отдельно.\nСпособ получения, стоимость и ориентировочный срок необходимо подтвердить при оформлении. Пока автоматический расчёт не введён в эксплуатацию, детали доставки уточняет менеджер — это не означает бесплатную доставку."},
 {"id":"tracking","title":"Статус и получение","body":"Следите за изменением статуса в личном кабинете. Когда перевозчик передаст трек-номер или ссылку отслеживания, используйте их для проверки движения посылки.\nПри получении сравните состав заказа с покупкой и осмотрите упаковку. Если заметили повреждение или несоответствие, зафиксируйте его и свяжитесь с магазином."},
 {"id":"questions","title":"Если нужно изменить заказ","body":"Напишите или позвоните нам как можно раньше, указав номер заказа и нужное изменение. Возможность корректировки зависит от того, началась ли сборка и передана ли посылка перевозчику.\nДля вопросов об отмене, недостатках или возврате используйте страницу «Правила возврата» и контакты магазина. Не отправляйте товар обратно без согласования адреса и порядка передачи."}
]$$::jsonb, false, CURRENT_TIMESTAMP),
('contacts', 'Давайте будем на связи', 'Контакты', 'Поможем с выбором продукта, заказом и сотрудничеством. Выберите удобный способ связи.', $$[
 {"id":"orders","title":"По вопросам покупки","body":"Телефон: 8 (918) 449-63-94.\nЭлектронная почта: info@sarkisianbrand.ru.\nЕсли вопрос связан с заказом, укажите его номер и кратко опишите ситуацию. Не отправляйте данные банковской карты, коды подтверждения и пароль от аккаунта."},
 {"id":"business","title":"Салонам и B2B-партнёрам","body":"Для профессиональных заказов используйте кабинет B2B. По вопросам подключения, ассортимента и сотрудничества можно написать на общую почту магазина.\nУкажите название организации и способ обратной связи — это поможет направить обращение нужному сотруднику."},
 {"id":"operator","title":"Реквизиты продавца","body":"Индивидуальный предприниматель Саркисян Светлана Гайковна.\nИНН: 931001394258. ОГРНИП: 323911200085753.\nПочтовый адрес: 350047, Краснодарский край, г. Краснодар, Проезд 1-й Линии, 2/1.\nПочтовый адрес не является автоматически адресом магазина, самовывоза или возврата. Такие посещения и отправления необходимо согласовать заранее."},
 {"id":"privacy","title":"Вопросы о персональных данных","body":"Для уточнения данных, запроса информации об обработке или отзыва согласия направьте обращение на info@sarkisianbrand.ru с темой «Персональные данные».\nНе прикладывайте копии документов без запроса: сначала сообщите, как с вами связаться и какого аккаунта или заказа касается обращение."}
]$$::jsonb, false, CURRENT_TIMESTAMP),
('privacy', 'Политика конфиденциальности', 'Документы', 'Как новая платформа SARKISIAN работает с данными покупателей и профессиональных клиентов.', $$[
 {"id":"operator","title":"1. Оператор и область действия","body":"Оператор: ИП Саркисян Светлана Гайковна, ИНН 931001394258, ОГРНИП 323911200085753. Для обращений: info@sarkisianbrand.ru; почтовый адрес: 350047, Краснодарский край, г. Краснодар, Проезд 1-й Линии, 2/1.\nДокумент относится к интернет-магазину и связанным клиентским кабинетам новой платформы. Он не описывает обработку данных на отключаемом сервисе Яндекс Кит. Использование отдельных внешних сервисов регулируется также документами их операторов."},
 {"id":"data","title":"2. Какие данные используются","body":"Для аккаунта и заказа: имя, контактные данные, сведения о получателе и адресе, состав и история заказов, результат оплаты. Для B2B: сведения об организации и её представителях, необходимые для профессионального обслуживания.\nПри обращении в поддержку используются текст обращения и добровольно предоставленные вложения. Технические данные и идентификаторы сессии нужны для входа, корзины, защиты и диагностики работы сервиса. Пароли не отображаются сотрудникам и хранятся в виде хешей."},
 {"id":"purposes","title":"3. Цели и основания","body":"Данные используются для создания и обслуживания аккаунта, исполнения заказа, связи с покупателем, поддержки и учёта обязательных документов. Правовое основание зависит от цели: исполнение договора, требования законодательства или отдельное согласие.\nРекламные сообщения не должны быть условием совершения покупки. Для них требуется отдельное согласие; его отзыв не отменяет обязательную обработку сведений об уже совершённой покупке."},
 {"id":"cookies","title":"4. Сессии и файлы cookie","body":"Платформа использует идентификаторы для работы входа и корзины. Избранное может сохраняться в браузере и синхронизироваться с аккаунтом. Очистка браузера или отключение cookie может повлиять на эти функции.\nНеобязательная аналитика и рекламные технологии должны включаться только после определения их состава и необходимого порядка согласия. Само наличие этой страницы не означает, что такие сервисы подключены."},
 {"id":"recipients","title":"5. Доступ и внешние сервисы","body":"Доступ сотрудникам предоставляется в соответствии с рабочими ролями. Для оплаты, фискализации, доставки, отправки уведомлений и учёта могут привлекаться подключённые поставщики услуг; передаются только сведения, необходимые для соответствующей операции.\nВход через внешнего провайдера выполняется, если он подключён и выбран пользователем. Для данных собственной клиентской базы B2B-партнёр должен самостоятельно определить основания обработки и необходимые согласия.\nПеред запуском необходимо утвердить фактический перечень получателей, договоры, место размещения баз данных и условия возможной трансграничной передачи."},
 {"id":"retention","title":"6. Хранение и защита","body":"Срок хранения определяется целью обработки и обязательными требованиями к учётным документам. Удаление аккаунта не означает немедленное уничтожение документов, которые требуется сохранять по закону.\nМеры защиты включают разграничение доступа, журналирование операций, защищённый обмен и резервное копирование. Их фактическое применение, сроки очистки резервных копий и инфраструктура должны быть подтверждены перед вводом платформы в эксплуатацию."},
 {"id":"rights","title":"7. Ваши обращения","body":"Вы можете обратиться за сведениями об обработке, уточнением, ограничением или удалением данных, а также отзывом согласия в случаях, предусмотренных законом. Напишите на info@sarkisianbrand.ru, указав контакт для ответа и предмет запроса.\nДля защиты аккаунта оператор может запросить разумное подтверждение принадлежности данных. Обращение рассматривается в применимые законодательные сроки. Действия оператора можно обжаловать в Роскомнадзор или суд."},
 {"id":"changes","title":"8. Изменения документа","body":"Актуальная редакция размещается на этой странице. Существенные изменения, затрагивающие основания или цели обработки, требуют отдельной оценки и, когда необходимо, нового согласия.\nЭта редакция подготовлена для разработки новой платформы и подлежит утверждению оператором до публичного запуска."}
]$$::jsonb, true, CURRENT_TIMESTAMP),
('oferta', 'Публичная оферта', 'Документы', 'Условия покупки товаров в интернет-магазине SARKISIAN. Редакция для новой платформы.', $$[
 {"id":"seller","title":"1. Продавец и покупатель","body":"Продавец: ИП Саркисян Светлана Гайковна, ИНН 931001394258, ОГРНИП 323911200085753. Контакт: info@sarkisianbrand.ru, телефон 8 (918) 449-63-94. Почтовый адрес: 350047, Краснодарский край, г. Краснодар, Проезд 1-й Линии, 2/1.\nДокумент описывает дистанционную розничную покупку в магазине. Профессиональные закупки для бизнеса могут регулироваться отдельным договором и условиями B2B-кабинета. Обязательные права потребителя не ограничиваются настоящим документом."},
 {"id":"product","title":"2. Товары и информация","body":"Ассортимент, цена и доступные варианты представлены в каталоге и карточке товара. Покупателю необходимо ознакомиться с описанием и рекомендациями производителя до использования.\nИзображение на экране может отличаться по цвету в зависимости от настроек устройства. Это не освобождает продавца от обязанности передать товар, соответствующий согласованным характеристикам."},
 {"id":"checkout","title":"3. Заказ и заключение договора","body":"Покупатель формирует корзину, сообщает сведения для исполнения заказа и подтверждает покупку после ознакомления с её итоговыми условиями. Подтверждение содержит состав заказа, стоимость, выбранный способ оплаты и согласованные условия доставки.\nПорядок акцепта и подтверждения заказа должен соответствовать окончательному сценарию оформления. При выявлении ошибки в наличии, цене или данных продавец связывается с покупателем для согласования; односторонняя подмена товара не допускается."},
 {"id":"price","title":"4. Цена и оплата","body":"Цены отображаются в рублях. Стоимость доставки указывается отдельно до окончательного подтверждения. Бонусы и промокоды применяются по опубликованным условиям соответствующей программы.\nОнлайн-оплата выполняется через подключённого провайдера. Кассовый чек предоставляется в соответствии с применимыми требованиями. При технической ошибке оплаты не повторяйте платёж без проверки его результата."},
 {"id":"delivery","title":"5. Доставка и передача","body":"Территория, способы и условия доставки согласовываются при оформлении. Доступные службы и ограничения описываются на странице «Доставка и оплата».\nПри получении желательно осмотреть упаковку и проверить комплектацию. Обнаруженные недостатки можно зафиксировать и сообщить продавцу; отсутствие фотографии или акта само по себе не отменяет обязательных прав покупателя."},
 {"id":"returns","title":"6. Отмена, недостатки и возврат","body":"Покупатель вправе направить запрос об отмене или возврате по контактам продавца. Применимые условия зависят от характера покупки, состояния и категории товара, наличия недостатков и требований законодательства.\nПорядок обращения опубликован на странице «Правила возврата». Условия документа не могут исключать законные требования по товару ненадлежащего качества. Возврат денег оформляется после проверки основания, согласованным законным способом."},
 {"id":"privacy","title":"7. Данные и разрешение вопросов","body":"Сведения покупателя используются для исполнения заказа и связанных обязательств. Подробности изложены в политике конфиденциальности. Согласие на рекламу оформляется отдельно от покупки.\nПо вопросам исполнения заказа направьте обращение на info@sarkisianbrand.ru с номером покупки и описанием ситуации. Споры разрешаются с соблюдением обязательных требований законодательства.\nДо публичного запуска оператор должен утвердить окончательные условия акцепта, оплаты, доставки и реквизиты настоящей оферты."}
]$$::jsonb, true, CURRENT_TIMESTAMP),
('returns', 'Правила возврата', 'Забота о покупателе', 'Если с покупкой что-то не так, расскажите нам. Поможем определить порядок действий без лишних пересылок.', $$[
 {"id":"request","title":"1. С чего начать","body":"Напишите на info@sarkisianbrand.ru или позвоните 8 (918) 449-63-94. Укажите номер заказа, товар и причину обращения. Если есть повреждение или ошибка комплектации, фотографии помогут быстрее разобраться, но не заменяют рассмотрение самого требования.\nНе отправляйте товар по почтовым реквизитам продавца без согласования: адрес для корреспонденции может отличаться от адреса приёма возвратов."},
 {"id":"cancel","title":"2. Отмена и товар без недостатков","body":"Сообщите об отмене как можно раньше. До передачи посылки перевозчику команда проверит возможность остановить сборку. После отправки порядок зависит от этапа доставки и применимых правил дистанционной продажи.\nВозможность возврата товара надлежащего качества оценивается по законодательству с учётом категории, способа приобретения и сохранности товара. Не распространяйте правила обмена обычной розничной покупки автоматически на дистанционный заказ."},
 {"id":"defect","title":"3. Недостаток или несоответствие","body":"Если получен не тот товар, не хватает позиции или обнаружен недостаток, сообщите об этом продавцу. По возможности сохраните упаковку и сведения о заказе до согласования дальнейших действий.\nТребования по товару ненадлежащего качества рассматриваются в соответствии с законом. Предварительное использование товара или отсутствие оригинального чека не являются автоматическим основанием отказать в рассмотрении обращения."},
 {"id":"transfer","title":"4. Передача и возврат денег","body":"После уточнения обращения команда сообщит адрес, способ передачи и необходимые сведения. Условия перевозки и её оплаты определяются основанием возврата и применимыми требованиями.\nСрок и способ возврата денег зависят от законного основания и платёжного сценария. Не сообщайте сотрудникам полный номер карты, срок действия, CVV и коды из сообщений. Для проверки покупки обычно достаточно номера заказа."},
 {"id":"b2b","title":"5. Профессиональные закупки","body":"Для покупок в предпринимательских целях применяются условия B2B-договора и соответствующие нормы законодательства. Обратитесь к менеджеру, указав организацию и номер профессионального заказа.\nПеред запуском необходимо утвердить конкретные сроки, адрес приёма, перечень условий по категориям и процедуру возврата в новой платформе. Эта страница является подготовленной редакцией для согласования."}
]$$::jsonb, true, CURRENT_TIMESTAMP);

UPDATE "StorefrontMenuItem" SET "url" = '/about', "updatedAt" = CURRENT_TIMESTAMP WHERE "url" IN ('/#about', '#about');
UPDATE "StorefrontMenuItem" SET "url" = '/delivery', "updatedAt" = CURRENT_TIMESTAMP WHERE "url" IN ('/#delivery', '#delivery');
UPDATE "StorefrontMenuItem" SET "url" = '/contacts', "updatedAt" = CURRENT_TIMESTAMP WHERE "url" IN ('/#contacts', '#contacts');
